#!/usr/bin/env python3
# Rigorous verifier for certificates produced by export.py.  Uses only exact integer arithmetic and ball arithmetic (python-flint).
#
# Field: K = k_{p^n}, the subfield of degree N = p^n of Q(zeta), zeta = exp(2 pi i / M), M = p^(n+1), p odd;
#   H = subgroup of order p-1 of (Z/M)^*, g a generator of (Z/M)^*, eta_i = sum_{h in H} zeta^(g^i h) (i mod N).
#   Gal(K/Q) is generated by sigma: eta_i -> eta_(i+1).  Elements: alpha = c + sum_i a_i eta_i (algebraic integers of K).
# Facts used: (1) a prime q != p splits completely in K iff q^(p-1) = 1 mod M;
#   (2) the prime of K above p is principal (it is generated by the norm of 1 - zeta);
#   (3) if every proper subfield of K has class number 1, then every prime of K above a prime that does not split completely is principal
#       (it is extended from the decomposition field);
#   (4) N(alpha) = prod_{j mod N} (c + sum_i a_i eta_(i+j)), and for a prime l = 1 mod M and z of order M modulo l,
#       eta_i = sum_{h in H} z^(g^i h) modulo a prime of Q(zeta) above l.
# Certificate lines:
#   "L q0 | c,i:a i:a ... ; ..."   elements with |N| = p^a q0^k lying in exactly k distinct primes above q0 (valuations 0 or 1);
#        check: the 0/1 vectors of all conjugates span Z^N  =>  every prime above q0 is principal.
#   "q | c | i:a ... | r^e ..."    |N(alpha)| = prod r^e, q || N(alpha), every r != q is p, a non-split prime, or certified by an earlier line
#        =>  (alpha) = Q * (principal ideal) with Q a prime above q  =>  every prime above q is principal (Galois conjugates).
import sys
from flint import fmpz, fmpz_mat, nmod_poly, arb, acb, ctx
def need(cond,msg):
    if not cond: raise SystemExit("FAILED: "+str(msg))
# Decimal strings for printed bounds and for the summaries, computed with integers only (no floating point):
#   up(x,k) is greater than every point of the ball x, down(x,k) is less than every point of the ball x; k digits after the point.
def _frac(x):                                         # exact value of an arb of radius 0, as (numerator, denominator)
    m,e=x.man_exp(); m,e=int(m),int(e)
    return (m<<e,1) if e>=0 else (m,1<<(-e))
def _dec(n,k):
    need(k>=1,"number of digits")
    s="%0*d"%(k+1,abs(n)); return ("-" if n<0 else "")+s[:-k]+"."+s[-k:]
def up(x,k): a,b=_frac(arb(x).upper()); return _dec(a*10**k//b+1,k)
def down(x,k): a,b=_frac(arb(x).lower()); return _dec(-((-a*10**k)//b)-1,k)
def is_prime(x): return x>1 and bool(fmpz(x).is_prime())
class K:
    def __init__(self,p,n):
        need(is_prime(p) and p>2 and n>=1,"field")
        self.p,self.n=p,n; self.N=N=p**n; self.M=M=p**(n+1); phi=(p-1)*N
        prs=set([p]+[d for d in range(2,p) if (p-1)%d==0 and is_prime(d)])
        self.g=g=next(x for x in range(2,M) if x%p and all(pow(x,phi//r,M)!=1 for r in prs))      # generator of (Z/M)^*
        self.H=[pow(g,N*t,M) for t in range(p-1)]; need(len(set(self.H))==p-1,"H")
        self.exps=[[pow(g,i,M)*h%M for h in self.H] for i in range(N)]
        need(sorted(e for ex in self.exps for e in ex)==[x for x in range(M) if x%p],"cosets of H")
        # auxiliary primes l = 1 mod M with a verified element z of order M, and eta_i mod l
        self.aux=[]; l=(2**61//M)*M+1
        while len(self.aux)<12:
            l+=M
            if not is_prime(l): continue
            z=next(pow(x,(l-1)//M,l) for x in range(2,200) if pow(pow(x,(l-1)//M,l),M//p,l)!=1)
            need(pow(z,M,l)==1 and pow(z,M//p,l)!=1,"root of unity")
            zp=[1]
            for _ in range(M-1): zp.append(zp[-1]*z%l)
            self.aux.append((l,[sum(zp[e] for e in ex)%l for ex in self.exps]))
    def split(self,q): return q!=self.p and pow(q,self.p-1,self.M)==1
    def norm(self,c,coef):                           # exact |N(alpha)|, by the Chinese remainder theorem
        N=self.N; b=abs(c)+(self.p-1)*sum(abs(a) for i,a in coef); bound=2*b**N+1
        mod=1; res=0
        for l,R in self.aux:
            if mod>bound: break
            v=1
            for j in range(N):
                v=v*(c+sum(a*R[(i+j)%N] for i,a in coef))%l
            res=res+mod*((v-res)*pow(mod,-1,l)%l); mod*=l       # res = v mod l, res unchanged mod the old modulus
        need(mod>bound,"not enough auxiliary primes")
        if res>mod//2: res-=mod
        return abs(res)
    def logrd(self):                                  # conductor-discriminant formula: phi(p^j) characters of conductor p^(j+1), j = 1..n
        p,n=self.p,self.n; ex=sum((p-1)*p**(j-1)*(j+1) for j in range(1,n+1))
        return arb(ex)/self.N*arb(p).log(), ex
    def hmin(self):                                   # least value of l^(order of l mod N) over primes l != p
        best=None; l=1
        while best is None or l<best:
            l+=1
            if l==self.p or not is_prime(l): continue
            f=1; x=l%self.N
            while x!=1: x=x*l%self.N; f+=1
            if best is None or l**f<best: best=l**f
        return best
def parse_coef(s): return [(int(t.split(":")[0]),int(t.split(":")[1])) for t in s.split()]
def lattice_block(F,q0,elems):
    N,M,p=F.N,F.M,F.p
    need(is_prime(q0) and F.split(q0),"seed prime")
    Phi=nmod_poly([1]*p,q0)(nmod_poly([0]*(M//p)+[1],q0))    # Phi_M(x) = Phi_p(x^(M/p))
    fac=Phi.factor()[1]
    need(len(fac)==N and all(e==1 and g.degree()==Phi.degree()//N for g,e in fac),"factorization of Phi_M mod q0: expected N factors")
    gs=[g for g,e in fac]; rows=[]
    for c,coef in elems:
        x=F.norm(c,coef); k=0
        while x%q0==0: x//=q0; k+=1
        while x%p==0: x//=p
        need(x==1 and k>=1,"lattice block: norm is not p^a q0^k")
        for s in range(N):
            co=[0]*M; co[0]=c%q0
            for i,a in coef:
                for e in F.exps[(i+s)%N]: co[e]=(co[e]+a)%q0
            A=nmod_poly(co,q0); pat=[1 if (A%g).is_zero() else 0 for g in gs]
            need(sum(pat)==k,"lattice block: a valuation exceeds 1")
            rows.append(pat)
    Hn=fmpz_mat(len(rows),N,[x for r in rows for x in r]).hnf()
    need(all(int(Hn[i,j])==(1 if i==j else 0) for i in range(N) for j in range(N)),"lattice block: the relations do not span Z^N")
def bound(F,primes,c):
    ctx.prec=200
    c=arb(c); pi=arb.pi(); gam=arb.const_euler(); logrd,_=F.logrd()
    Fn=lambda x:(-(x/c)**2).exp()/(x/2).cosh()
    eps=arb(1)/1000; Mx=arb(200)
    f=lambda x,_:(1-(-(x/c)**2).exp()/(x/2).cosh())/2*(1/(x/2).sinh()+1/(x/2).cosh())
    mid=acb.integral(f,acb(eps),acb(Mx)).real
    head=(1/c**2+arb(1)/8)*(eps**2/2+eps**3/6); tail=(1/(1-(-Mx).exp())+1)*2*(-Mx/2).exp()
    I_up=(mid+head+tail).upper(); S=arb(0)
    for q in primes:
        lq=arb(q).log()
        for m in range(1,9): S+=2*lq/arb(q)**(arb(m)/2)*Fn(m*lq)
    S_low=S.lower(); B=(pi/2+gam+(8*pi).log()-logrd-I_up+S_low).lower()
    return I_up,S_low,B,((2*c*pi.sqrt()/(F.N*B)).upper() if B>0 else None)
def split_primes(F,A,B):                         # proven split primes q with A <= q < B
    M=F.M; res=[]
    for r in range(M):
        if r%F.p and pow(r,F.p-1,M)==1:
            q=A-(A%M)+r
            if q<A: q+=M
            while q<B:
                if is_prime(q): res.append(q)
                q+=M
    return sorted(res)
def partial_sums(F,primes,cs):                  # rigorous lower bounds of the sums over the given primes, as decimal strings
    ctx.prec=200; out={}
    for c in cs:
        ca=arb(c); S=arb(0)
        for q in primes:
            lq=arb(q).log()
            for m in range(1,9): S+=2*lq/arb(q)**(arb(m)/2)*((-(m*lq/ca)**2).exp()/(m*lq/2).cosh())
        out[c]=down(S.lower(),13)
    return out
def read_rows(F,fn):
    for line in open(fn):
        line=line.strip()
        if not line or line.startswith("#"): continue
        if line.startswith("L "): yield ("L",line); continue
        qs,cs_,coefs,facs=line.split("|"); q=int(qs); c=int(cs_); coef=parse_coef(coefs)
        fac=[(int(t.split("^")[0]),int(t.split("^")[1])) for t in facs.split()]
        need(all(0<=i<F.N and a!=0 for i,a in coef) and len(set(i for i,a in coef))==len(coef),"%d: coefficients"%q)
        prod=1
        for r,e in fac:
            need(e>=1 and is_prime(r),"%d: factor %d is not prime"%(q,r)); prod*=r**e
        need(len(set(r for r,e in fac))==len(fac) and F.norm(c,coef)==prod,"%d: norm"%q)
        need(F.split(q) and dict(fac).get(q)==1,"%d: q must be a split prime dividing the norm exactly once"%q)
        yield (q,fac)
def main():
    import json
    args=sys.argv[1:]; fn=args[0]; opt={args[i]:args[i+1:i+3] for i in range(1,len(args)) if args[i].startswith("--")}
    cs=[int(x) for x in opt["--c"][0].split(",")] if "--c" in opt else [60,80,100,150,200]
    first=open(fn).readline().split(); need(first[:2]==["#","field"],"missing field line"); F=K(int(first[2]),int(first[3]))
    cert=set(); nrows=0
    if "--range" in opt:
        # Rule for this mode: every split prime factor r != q of the norm satisfies r < q.  Together with completeness
        # (every split prime in [A,B) has a row) and the same statement for all split primes < A, induction on q shows
        # that every prime above a split prime < B is principal.
        A,B=int(opt["--range"][0]),int(opt["--range"][1])
        for item in read_rows(F,fn):
            need(item[0]!="L","lattice blocks are not allowed in range mode")
            q,fac=item; need(A<=q<B,"%d: outside the range"%q)
            for r,e in fac: need(r==q or r==F.p or (not F.split(r)) or r<q,"%d: split prime factor %d is not smaller than q"%(q,r))
            cert.add(q); nrows+=1
        sp=split_primes(F,A,B); miss=[q for q in sp if q not in cert]
        need(not miss,"range [%d,%d): %d split primes without a row, e.g. %s"%(A,B,len(miss),miss[:5]))
        need(len(cert)==len(sp),"rows for primes outside the list of split primes")
        res={"field":[F.p,F.n],"range":[A,B],"rows":nrows,"split_primes":len(sp),"sums":partial_sums(F,sp,cs)}
        print("RANGE PASS "+json.dumps(res)); return
    for item in read_rows(F,fn):
        if item[0]=="L":
            head,body=item[1][2:].split("|"); q0=int(head)
            elems=[(int(e.split(",")[0]),parse_coef(e.split(",")[1])) for e in body.split(";")]
            lattice_block(F,q0,elems); cert.add(q0); print("lattice block: the primes above %d are principal (%d elements)"%(q0,len(elems)),flush=True); continue
        q,fac=item
        for r,e in fac: need(r==q or r==F.p or (not F.split(r)) or r in cert,"%d: prime factor %d is not known to be principal"%(q,r))
        cert.add(q); nrows+=1
    S=sorted(cert)
    print("rows verified: %d; split primes proved principal: %d (largest %d)"%(nrows,len(S),S[-1]))
    if "--complete" in opt:
        A=int(opt["--complete"][0]); sp=split_primes(F,0,A); miss=[q for q in sp if q not in cert]
        need(not miss,"%d split primes below %d without a row, e.g. %s"%(len(miss),A,miss[:5]))
        res={"field":[F.p,F.n],"range":[0,A],"rows":nrows,"split_primes":len(sp),"sums":partial_sums(F,sp,cs)}
        print("BASE PASS "+json.dumps(res)); return
    logrd,ex=F.logrd(); hm=F.hmin(); best=None
    print("field k_{%d^%d}: degree %d, discriminant %d^%d, least possible class number > 1 (rank theorem, given class number 1 for proper subfields, p excluded by Iwasawa): %d"%(F.p,F.n,F.N,F.p,ex,hm))
    for c in cs:
        I_up,S_low,B,hb=bound(F,S,c)
        print("c=%d: integral <= %s, prime sum >= %s, B >= %s"%(c,up(I_up,10),down(S_low,10),down(B,7))+("" if hb is None else ", h < %s"%up(hb,4)))
        if hb is not None and (best is None or hb<best): best=hb
    if best is not None and best<hm: print("VERDICT: PASS  (h < %s < %d)"%(up(best,4),hm))
    else: print("VERDICT: bound not below %d"%hm)
if __name__=="__main__": main()
